package org.apache.commons.math.analysis.solvers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.NumberIsTooSmallException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.mockito.Mockito.when;

public class BrentSolver_solve_TriageGen1Test {

    private BrentSolver solver;

    @Mock
    private UnivariateRealFunction function;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        solver = new BrentSolver();
    }

    /**
     * Test case: Initial guess is already a root (Math.abs(yInitial) <= functionValueAccuracy)
     */
    @Test
    public void testSolve_InitialGuessIsRoot() throws Exception {
        double initial = 2.0;
        double min = 0.0;
        double max = 5.0;
        // Accuracy is typically 1e-14 in BrentSolver
        when(function.value(initial)).thenReturn(0.0);

        double result = solver.solve(function, min, max, initial);
        assertEquals(initial, result, 1e-14);
    }

    /**
     * Test case: Min endpoint is already a root (Math.abs(yMin) <= functionValueAccuracy)
     */
    @Test
    public void testSolve_MinIsRoot() throws Exception {
        double initial = 2.0;
        double min = 1.0;
        double max = 5.0;
        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(0.0);

        double result = solver.solve(function, min, max, initial);
        assertEquals(min, result, 1e-14);
    }

    /**
     * Test case: Max endpoint is already a root (Math.abs(yMax) <= functionValueAccuracy)
     */
    @Test
    public void testSolve_MaxIsRoot() throws Exception {
        double initial = 2.0;
        double min = 0.0;
        double max = 3.0;
        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(1.0);
        when(function.value(max)).thenReturn(0.0);

        double result = solver.solve(function, min, max, initial);
        assertEquals(max, result, 1e-14);
    }

    /**
     * Test case: Initial and Min bracket the root (yInitial * yMin < 0)
     */
    @Test
    public void testSolve_InitialAndMinBracket() throws Exception {
        double initial = 2.0;
        double min = 1.0;
        double max = 5.0;
        // f(2)=1, f(1)=-1 -> root between 1 and 2
        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(-1.0);
        // For the recursive call to succeed, we need a root in the new interval
        when(function.value(1.5)).thenReturn(0.0); 

        double result = solver.solve(function, min, max, initial);
        // Since we mocked a root at 1.5 for the recursive call
        assertEquals(1.5, result, 1e-14);
    }

    /**
     * Test case: Initial and Max bracket the root (yInitial * yMax < 0)
     */
    @Test
    public void testSolve_InitialAndMaxBracket() throws Exception {
        double initial = 2.0;
        double min = 0.0;
        double max = 5.0;
        // f(2)=1, f(5)=-1 -> root between 2 and 5
        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(1.0);
        when(function.value(max)).thenReturn(-1.0);
        // Mock root for recursive call
        when(function.value(3.5)).thenReturn(0.0);

        double result = solver.solve(function, min, max, initial);
        assertEquals(3.5, result, 1e-14);
    }

    /**
     * Test case: No bracketing (yMin * yMax > 0)
     */
    @Test
    public void testSolve_NoBracketingThrowsException() throws Exception {
        double initial = 2.0;
        double min = 0.0;
        double max = 5.0;
        // f(2)=1, f(0)=1, f(5)=1 -> no sign change
        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(1.0);
        when(function.value(max)).thenReturn(1.0);

        assertThrows(IllegalArgumentException.class, () -> {
            solver.solve(function, min, max, initial);
        });
    }

    /**
     * Test case: Full Brent algorithm (yMin * yMax < 0 and initial is outside bracket)
     */
    @Test
    public void testSolve_FullBrentAlgorithm() throws Exception {
        double initial = 0.5;
        double min = 0.0;
        double max = 2.0;
        // f(0.5)=1, f(0)=-1, f(2)=1. 
        // Min and Max bracket the root (f(0)*f(2) < 0 is false, but logic goes to full Brent)
        // To hit the final 'return solve(f, min, yMin, max, yMax, initial, yInitial)'
        // We need yMin * yMax < 0
        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(1.0);
        when(function.value(max)).thenReturn(-1.0);

        // The root is at 1.5
        when(function.value(1.5)).thenReturn(0.0);

        double result = solver.solve(function, min, max, initial);
        assertEquals(1.5, result, 1e-14);
    }

    /**
     * Test case: Invalid sequence (min > max) to trigger verifySequence
     */
    @Test
    public void testSolve_InvalidSequence() {
        assertThrows(IllegalArgumentException.class, () -> {
            solver.solve(function, 5.0, 0.0, 2.0);
        });
    }
}
